import time
import logging

def safe_tool_executor(tool_func, **kwargs) -> str:
    """Executes a tool safely and returns a string observation for the agent."""
    try:
        result = tool_func(**kwargs)
        return f'SUCCESS: {result}'
    except KeyError as e:
        return f'OBSERVATION ERROR: Missing expected parameter: {e}. Please correct your parameters.'
    except TimeoutError:
        return 'OBSERVATION ERROR: Tool timed out while contacting external API. Try an alternative tool or query.'
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
        return f'OBSERVATION ERROR: Tool execution failed due to: {type(e).__name__}: {str(e)}'

def divide_tool(a: float, b: float) -> float:
    if b == 0:
        raise ZeroDivisionError('Cannot divide by zer✅')
    return a / b

print(safe_tool_executor(divide_tool, a=10, b=0))
print(safe_tool_executor(divide_tool, a=10, b=2))
